function build(){if(root)return;root=document.createElement('section');root.id='terranexus-overlay';root.innerHTML='<div class="tn-top"><div class="tn-logo"><span>✦</span><div><b>TERRANEXUS</b><small>HOLOGRAPHIC SCIENCE WORKSHOP</small></div></div><div class="tn-live">● WORKSHOP ONLINE · INTERACTIVE 3D</div><div class="tn-actions"><button id="tn-show-study" class="tn-show-panel">OPEN STUDY</button><button id="tn-show-inspector" class="tn-show-panel">OPEN INSPECTOR</button><button id="tn-settings">⚙ SETTINGS</button><button id="tn-close">↙ JARVIS</button></div></div><div class="tn-layout"><aside class="tn-side"><button class="tn-side-x" id="tn-hide-study" aria-label="Hide study panel">×</button><small class="tn-kicker">01 / CURRENT STUDY</small><h2 id="tn-title"></h2><p id="tn-summary"></p><small class="tn-kicker">DEMONSTRATION LIBRARY</small><div id="tn-demos" class="tn-demos"></div><small class="tn-kicker">PERIODIC TABLE · 118 ELEMENTS</small><div id="tn-elements" class="tn-elements"></div><p class="tn-note">Drag to rotate · scroll to zoom · select parts to inspect.</p></aside><main class="tn-center"><div class="tn-stage-title"><span>WORKSHOP / LIVE MODEL</span><span id="tn-badge">3D MODEL</span></div><div id="tn-stage"><div class="tn-loading">Preparing holographic workshop…</div><div class="tn-caption" id="tn-caption">Interactive 3D model</div></div><div class="tn-controls"><button id="tn-rotate">⟳ AUTO ROTATE</button><button id="tn-explode">✣ EXPLODE PARTS</button><button id="tn-zoom-out" title="Zoom out" aria-label="Zoom out">− ZOOM</button><button id="tn-zoom-in" title="Zoom in" aria-label="Zoom in">＋ ZOOM</button><button id="tn-reset">↺ RESET VIEW</button><span id="tn-state">MODEL READY</span></div><div id="tn-reaction" class="tn-reaction"><span id="tn-equation">Balanced atom rearrangement</span><button id="tn-run">▶ RUN REACTION</button></div></main><aside class="tn-side tn-inspector"><button class="tn-side-x" id="tn-hide-inspector" aria-label="Hide inspector panel">×</button><small class="tn-kicker">02 / COMPONENT INSPECTOR</small><small class="tn-sub">SELECTED COMPONENT</small><h2 id="tn-part"></h2><p id="tn-info"></p><small class="tn-kicker">KEY PRINCIPLES</small><p id="tn-facts" class="tn-facts"></p><small class="tn-kicker">MODEL PARTS</small><div id="tn-parts" class="tn-parts"></div><p class="tn-note">Tap a 3D component or choose it here to inspect.</p></aside></div><footer class="tn-console"><span class="tn-command-icon">⌘</span><div class="tn-input-wrap"><label for="tn-input">COMMAND CONSOLE</label><input id="tn-input" placeholder="Show a magnetic field, wave, lens, animal cell, greenhouse or hydraulic press…" autocomplete="off"><small id="tn-status">Built-in demonstrations work without an API key.</small></div><button id="tn-voice">🎙</button><button id="tn-send">SEND ↗</button></footer><div id="tn-modal" class="tn-modal-bg" hidden><div class="tn-modal"><button id="tn-x" class="tn-x">×</button><small class="tn-kicker">OPTIONAL AI CONNECTION</small><h2>Workshop intelligence</h2><p>Built-in models and explanations are free. Optionally paste your own Gemini API key for open-ended explanations. It is kept only in this browser session and sent directly to Google, not to a JARVIS server.</p><label for="tn-key">GEMINI API KEY</label><input id="tn-key" type="password" autocomplete="off" placeholder="Optional key"><div class="tn-modal-actions"><button id="tn-remove">REMOVE KEY</button><button id="tn-save">SAVE KEY</button></div><small id="tn-key-status">No key needed for built-in demos.</small><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noopener">Get a key from Google AI Studio ↗</a></div></div>';document.body.appendChild(root);fillDemos();fillElements();bind();update();loadThree().then(ok=>{if(ok)init3d();else fallback()})}
function fillDemos(){const labels={atom:'Atomic structure',water:'Water molecule',methane:'Methane CH₄',co2:'Carbon dioxide',combustion:'Combustion reaction',photosynthesis:'Photosynthesis',engine:'Cutaway engine',gears:'Gear train',motor:'Electric motor',pendulum:'Pendulum',lever:'Lever',solar:'Solar system',dna:'DNA helix',projectile:'Projectile motion',spring:'Spring–mass oscillator',collision:'Elastic collision',circuit:'Electric circuit',ammonia:'Ammonia NH₃',benzene:'Benzene ring',magnet:'Magnetic field',wave:'Transverse wave',optics:'Convex lens & rays',cell:'Animal cell',greenhouse:'Greenhouse effect',hydraulic:'Hydraulic press',orbital:'Quantum orbitals',thermo:'Heat engine · thermodynamics',electrolysis:'Water electrolysis',torque:'Torque & rotational equilibrium',interference:'Wave interference',kinetics:'Reaction energy profile',stress:'Stress–strain response',orbitalmotion:'Orbital mechanics'};$('tn-demos').innerHTML=Object.keys(labels).map(id=>'<button data-demo="'+id+'" class="'+(id===active?'on':'')+'"><span>'+({'atom':'◉','water':'◌','methane':'◇','co2':'⇄','combustion':'✧','photosynthesis':'❋','engine':'⚙','gears':'⚙','motor':'ϟ','pendulum':'◒','lever':'⌁','solar':'☼','dna':'⌘','projectile':'➤','spring':'〰','collision':'↔','circuit':'ϟ','ammonia':'△','benzene':'⬡','magnet':'🧲','wave':'〰','optics':'◉','cell':'◍','greenhouse':'☼','hydraulic':'↕'}[id])+'</span>'+labels[id]+'<b>↗</b></button>').join('')}
