function bind(){ const layout=()=>root&&root.querySelector('.tn-layout');$('tn-hide-study').onclick=()=>layout()?.classList.add('tn-hide-left');$('tn-hide-inspector').onclick=()=>layout()?.classList.add('tn-hide-right');$('tn-show-study').onclick=()=>layout()?.classList.remove('tn-hide-left');$('tn-show-inspector').onclick=()=>layout()?.classList.remove('tn-hide-right');$('tn-close').onclick=close;$('tn-settings').onclick=()=>{$('tn-modal').hidden=false;$('tn-key').value=sessionStorage.getItem('tnGeminiKey')||''};$('tn-x').onclick=()=>$('tn-modal').hidden=true;$('tn-modal').onclick=e=>{if(e.target===$('tn-modal'))$('tn-modal').hidden=true};$('tn-save').onclick=()=>{if(!$('tn-key').value.trim()){$('tn-key-status').textContent='Paste a key first.';return}sessionStorage.setItem('tnGeminiKey',$('tn-key').value.trim());$('tn-key-status').textContent='Saved for this browser session.'};$('tn-remove').onclick=()=>{sessionStorage.removeItem('tnGeminiKey');$('tn-key').value='';$('tn-key-status').textContent='Key removed.'};$('tn-demos').onclick=e=>{let b=e.target.closest('[data-demo]');if(b)show(b.dataset.demo)};$('tn-elements').onclick=e=>{let b=e.target.closest('[data-el]');if(b){element=els.find(x=>x.sym===b.dataset.el)||element;show('atom');part=element.name;update()}};$('tn-parts').onclick=e=>{let b=e.target.closest('[data-part]');if(b){part=b.dataset.part;highlight();update()}};$('tn-send').onclick=command;$('tn-input').onkeydown=e=>{if(e.key==='Enter')command()};$('tn-voice').onclick=listen;$('tn-explode').onclick=()=>{explode=!explode;$('tn-explode').classList.toggle('on',explode);$('tn-state').textContent=explode?'EXPLODED VIEW':'MODEL READY';show(active)};$('tn-rotate').onclick=()=>{$('tn-rotate').classList.toggle('on');$('tn-rotate').dataset.on=$('tn-rotate').dataset.on==='1'?'0':'1'};const zoomBy=delta=>{if(camera){camera.position.z=Math.max(2.4,Math.min(18,camera.position.z+delta));camera.updateProjectionMatrix();$('tn-state').textContent=camera.position.z<5?'ZOOMED IN':camera.position.z>10?'ZOOMED OUT':'MODEL READY'}};$('tn-zoom-in').onclick=()=>zoomBy(-.8);$('tn-zoom-out').onclick=()=>zoomBy(.8);$('tn-reset').onclick=()=>{rotX=.15;rotY=.4;if(camera)camera.position.set(0,0,['engine','solar','greenhouse','cell','thermo','orbitalmotion'].includes(active)?9:['stress','interference','kinetics'].includes(active)?8:7);if(model)model.rotation.set(0,0,0);$('tn-state').textContent='VIEW RESET'};$('tn-run').onclick=()=>{$('tn-status').textContent=$('tn-equation').textContent+' · Conceptual atom conservation demonstration.';$('tn-state').textContent='REACTION SIMULATED';model&&model.scale.set(.8,.8,.8);setTimeout(()=>{if(model)model.scale.set(1,1,1);$('tn-state').textContent='MODEL READY'},800)};const st=$('tn-stage');st.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY;st.setPointerCapture&&st.setPointerCapture(e.pointerId)};st.onpointermove=e=>{if(drag){rotY+=(e.clientX-lastX)*.008;rotX+=(e.clientY-lastY)*.008;lastX=e.clientX;lastY=e.clientY}};['pointerup','pointercancel','pointerleave'].forEach(n=>st.addEventListener(n,()=>drag=false));st.addEventListener('wheel',e=>{if(camera)camera.position.z=Math.max(3,Math.min(15,camera.position.z+Math.sign(e.deltaY)*.5))},{passive:true});st.addEventListener('click',e=>{if(!ray||!renderer)return;let r=renderer.domElement.getBoundingClientRect();vec.x=(e.clientX-r.left)/r.width*2-1;vec.y=-(e.clientY-r.top)/r.height*2+1;ray.setFromCamera(vec,camera);let h=ray.intersectObjects(meshes,true);if(h.length){part=h[0].object.userData.part||h[0].object.parent.userData.part;if(part){highlight();update()}}})}
function loadThree(){if(window.THREE)return Promise.resolve(true);return new Promise(resolve=>{let s=document.createElement('script');s.src=URL3;s.onload=()=>resolve(!!window.THREE);s.onerror=()=>resolve(false);document.head.appendChild(s)})}
function init3d(){try{const st=$('tn-stage');st.querySelector('.tn-loading').remove();scene=new THREE.Scene();scene.background=new THREE.Color(0x100b08);camera=new THREE.PerspectiveCamera(42,st.clientWidth/Math.max(st.clientHeight,1),.1,100);camera.position.z=7;renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));renderer.setSize(st.clientWidth,st.clientHeight);renderer.outputEncoding=THREE.sRGBEncoding;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.domElement.style.cssText='position:absolute;inset:0;width:100%;height:100%;touch-action:none';st.prepend(renderer.domElement);scene.add(new THREE.HemisphereLight(0xdde9ff,0x25160e,1.15));let l=new THREE.DirectionalLight(0xffd4a0,2.35);l.position.set(4,7,6);l.castShadow=true;l.shadow.mapSize.set(1024,1024);l.shadow.camera.left=-7;l.shadow.camera.right=7;l.shadow.camera.top=7;l.shadow.camera.bottom=-7;scene.add(l);let fill=new THREE.PointLight(0x4d9dff,.7,18);fill.position.set(-4,2,3);scene.add(fill);let rim=new THREE.PointLight(0xff8b36,.65,18);rim.position.set(2,3,-4);scene.add(rim);let grid=new THREE.GridHelper(16,32,0xb65d1b,0x382014);grid.position.y=-2;grid.material.transparent=true;grid.material.opacity=.26;scene.add(grid);let floor=new THREE.Mesh(new THREE.PlaneGeometry(30,30),new THREE.MeshStandardMaterial({color:0x17100c,metalness:.18,roughness:.72}));floor.rotation.x=-Math.PI/2;floor.position.y=-2.04;floor.receiveShadow=true;scene.add(floor);ray=new THREE.Raycaster();vec=new THREE.Vector2();window.addEventListener('resize',resize);ready=true;loop();show(active)}catch(e){fallback()}}
