function drawSolar(){ball('Sun',0,0,0,.58,0xf2b06e);const colors=[0xa68f78,0xd3a87d,0xd7a069,0xc79664,0xd2af8c,0xc4a17d,0xcaa279,0xd3a372];for(let i=0;i<8;i++){const r=1+i*.34,ring=add(new THREE.TorusGeometry(r,.008,6,100),'Orbit path',0,0,0,0xcfb295);ring.rotation.x=Math.PI/2;const planet=ball(['Mercury','Venus','Earth','Mars','Jupiter','Saturn','Uranus','Neptune'][i],Math.cos(i*.8)*r,0,Math.sin(i*.8)*r,.08+(i===4?.12:0),colors[i]);planet.userData.solarOrbit={r:r,a:i*.8,speed:.22/(1+i*.28)}}}
function drawReaction(id){if(id==='combustion'){ball('Methane',-1.3,0,0,.4,0xd09e6c);ball('Oxygen',-.3,.35,0,.25,0xe9b077);ball('Oxygen',-.3,-.35,0,.25,0xe9b077);ball('Carbon dioxide',1.1,.3,0,.3,0xd09e6c);ball('Water',1.1,-.4,0,.25,0xcfa070);wire([-.75,0,0],[.5,0,0],0xe4a668)}else{ball('Carbon dioxide',-1.2,.35,0,.3,0xd09e6c);ball('Water',-1.2,-.35,0,.25,0xcfa070);ball('Glucose',.7,0,0,.55,0xd7a26d);for(let i=0;i<3;i++)ball('Oxygen',1.5,.6-i*.6,0,.18,0xe9b077)}}
function drawProjectile(){add(new THREE.BoxGeometry(5,.05,.7),'Ground plane',0,-1.75,0,0x4a4037);const ballObj=ball('Projectile',-2,-1.1,0,.19,0xd66f32);ballObj.userData.projectile=true;ballObj.userData.startTick=tick;wire([-2,-1.7,0],[2.2,-1.7,0],0x9a8069);const pts=[];for(let i=0;i<=40;i++){const t=i/40*2.5;pts.push(new THREE.Vector3(-2+1.55*t,-1.1+1.9*t-.5*.82*t*t,.02))}const path=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineDashedMaterial({color:0xffbd78,dashSize:.08,gapSize:.055}));path.computeLineDistances();model.add(path)}
function drawSpring(){add(new THREE.BoxGeometry(2.1,.12,.8),'Support',0,1.5,0,0x8d8174);const pts=[];for(let i=0;i<80;i++){const y=1.45-i/79*1.6;const a=i/79*Math.PI*2*9;pts.push(new THREE.Vector3(Math.cos(a)*.18,y,Math.sin(a)*.18))}const spring=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0xc7d8e8}));spring.userData.springLine=true;model.add(spring);const mass=add(new THREE.BoxGeometry(.72,.48,.55),'Mass',0,-.45,0,0x7399ba);mass.userData.springMass=true;add(new THREE.BoxGeometry(2.3,.08,.8),'Base',0,-1.5,0,0x75685c)}
function drawCollision(){add(new THREE.BoxGeometry(4.5,.08,.8),'Track',0,-1.3,0,0x82796f);for(let i=0;i<7;i++)add(new THREE.CylinderGeometry(.025,.025,.65,10),'Track roller',-1.8+i*.6,-1.66,0,0xb3a18d);const a=ball('Mass A',-1.25,-.95,0,.38,0x4b9bd4);a.userData.collisionMass=1;const b=ball('Mass B',1.25,-.95,0,.38,0xe2a05a);b.userData.collisionMass=2;wire([-2.2,-.55,0],[2.2,-.55,0],0xbda68e)}
function drawCircuit(){const metal=0xb7c5ce;add(new THREE.BoxGeometry(.7,1.25,.24),'Battery',-1.5,0,0,0x435f73);add(new THREE.BoxGeometry(.16,.34,.27),'Positive terminal',-1.5,.79,0,0xe4b45f);add(new THREE.BoxGeometry(.16,.2,.27),'Negative terminal',-1.5,-.72,0,0x87939a);const points=[[-1.5,.63,0],[-.8,.63,0],[.65,.63,0],[1.5,.63,0],[1.5,-.63,0],[-1.5,-.63,0],[-1.5,.63,0]];for(let i=0;i<points.length-1;i++)wire(points[i],points[i+1],metal);add(new THREE.BoxGeometry(.58,.26,.3),'Resistor',0,.63,0,0xc88750);const led=ball('LED',1.5,0,0,.22,0x6be6a5);led.material.emissive.setHex(0x1a9b62);led.material.emissiveIntensity=.75;for(let i=0;i<8;i++){const p=ball('Electron',-1.5+(i%4)*.78,i<4?.63:-.63,0,.055,0x71d7ff);p.userData.circuitElectron=i}}
