function drawDNA(){for(let i=0;i<64;i++){let t=i*.24,y=(i-32)*.055,x=Math.cos(t)*.7,z=Math.sin(t)*.7,x2=Math.cos(t+Math.PI)*.7,z2=Math.sin(t+Math.PI)*.7;ball('DNA strand A',x,y,z,.07,0xb99066);ball('DNA strand B',x2,y,z2,.07,0xd6a97c);if(i%4===0)wire([x,y,z],[x2,y,z2],0xe6ac72)}}
